export const $ = (s) => document.querySelector(s);
export const esc = (v) =>
  String(v ?? "").replace(
    /[&<>"']/g,
    (c) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[
        c
      ],
  );
export const icon = (n) =>
  '<i class="icon" aria-hidden="true" style="--icon:url(/assets/icons/' +
  n +
  '.svg)"></i>';
export async function api(path, method = "GET", data) {
  const init = { method, headers: { "X-CyberShield": "1" } };
  if (data instanceof File) {
    const extension = data.name.match(/\.([a-z0-9]{1,8})$/i);
    if (extension)
      init.headers["X-File-Extension"] = extension[1].toLowerCase();
    init.body = data;
  } else if (data !== undefined) {
    init.headers["Content-Type"] = "application/json";
    init.body = JSON.stringify(data);
  }
  init.signal = AbortSignal.timeout(
    data instanceof File ? 45000 : path === "check-url" ? 30000 : 20000,
  );
  let response;
  try {
    response = await fetch("/api/" + path, init);
  } catch (error) {
    throw Error(
      error.name === "TimeoutError"
        ? "The request timed out. Check the server connection and retry."
        : "Cannot reach CyberShield. Start the local CyberShield server and reload the page.",
    );
  }
  const result = await response.json();
  if (!response.ok) {
    const error = new Error(result.error || "Request failed.");
    error.status = response.status;
    throw error;
  }
  return result;
}
export function submit(form, fn) {
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const button = event.submitter || form.querySelector("button");
    if (button.disabled) return;
    const msg = form.querySelector("output") || $("#status");
    if (msg) msg.textContent = "Working…";
    button.disabled = true;
    try {
      const info = await fn(Object.fromEntries(new FormData(form)), form);
      if (msg) msg.textContent = info || "";
    } catch (e) {
      if (msg) msg.textContent = e.message;
    } finally {
      button.disabled = false;
    }
  });
}
export function theme(t) {
  const mq = matchMedia("(prefers-color-scheme:light)");
  const apply = () =>
    (document.documentElement.dataset.theme =
      t === "system" ? (mq.matches ? "light" : "dark") : t);
  apply();
  mq.onchange = apply;
}
export const date = (v) =>
  v ? new Date(v.replace(" ", "T") + "Z").toLocaleString() : "";
export const input = (name, label, type = "text", max = 120, extra = "") =>
  "<label>" +
  label +
  '<input name="' +
  name +
  '" type="' +
  type +
  '" maxlength="' +
  max +
  '" ' +
  extra +
  "></label>";
export const area = (name, label, max, required = "") =>
  "<label>" +
  label +
  '<textarea name="' +
  name +
  '" maxlength="' +
  max +
  '" ' +
  required +
  "></textarea></label>";
export const options = (items) =>
  items.map((i) => "<option>" + esc(i) + "</option>").join("");
export const card = (title, body) =>
  '<section class="card"><h2>' + title + "</h2>" + body + "</section>";
export const brand =
  '<a class="brand" href="/home.html" aria-label="CyberShield home"><img class="wordmark" data-cs-image="logo" src="data:image/png;base64," alt="CyberShield"></a>';
